/** Whether a string names a task icon of this set. */
export function isTaskIconName(name: string): name is TaskIconName {
  return (taskIconNames as readonly string[]).includes(name)
}

/** Custom element tag name for a task icon, e.g. `video-call` -> `c2-task-icon-video-call`. */
export function taskIconTag(name: TaskIconName): `c2-task-icon-${TaskIconName}` {
  return `c2-task-icon-${name}`
}
